ACMsg.STM32_HT16K33SEGMENTBIG_HT16K33SEGMENTBIG_SET_COLON = "اضبط أو ألغِ ضبط أضواء النقطتين ونقاط عشرية في شاشة المقاطع. تقوم هذه الطريقة بتحديث مخزن العرض، لكنها لا ترسل المخزن إلى الشاشة نفسها. استدعِ 'draw()' لعرض المخزن على الشاشة. الوسيطات: patter (int) عدد صحيح يحدد العناصر التي ستُضاء (أو القيم المطلوبة مدموجة بواسطة OR). الافتراضي: 0x00 0x00: لا نقطتين 0x02: النقطتان المركزيتان 0x04: النقطتان اليساريتان، النقطة السفلية 0x08: النقطتان اليساريتان، النقطة العلوية 0x10: النقطة العشرية (عليا) إرجاع: النسخة (self)";
ACMsg.STM32_HT16K33SEGMENTBIG_HT16K33SEGMENTBIG_SET_GLYPH = "اعرض رمزاً معرفاً من قبل المستخدم عند الرقم المحدد. قيم الرموز هي أعداد صحيحة 8-بت تمثل نمط المقاطع المضيئة. تُحسب القيمة بتعيين البت(ات) التي تمثل المقاطع المراد إضاءتها. تخطيط البت إلى المقطع يدور باتجاه عقارب الساعة من الأعلى حول محيط المصفوفة؛ المقطع الداخلي هو البت 6: 0 _ 5 |   | 1 |   | - <----- 6 4 |   | 2 | _ | 3 تقوم هذه الطريقة بتحديث مخزن العرض، لكنها لا ترسل المخزن إلى الشاشة نفسها. استدعِ 'update()' لعرض المخزن على الشاشة. الوسيطات: glyph (int): نمط الرمز. digit (int): الرقم الذي سيعرض الرمز. الافتراضي: 0 (الرقم الأيسر). إرجاع: النسخة (self)";
ACMsg.STM32_HT16K33SEGMENTBIG_HT16K33SEGMENTBIG_SET_NUMBER = "اعرض قيمة عشرية مفردة (0-9) عند الرقم المحدد. تقوم هذه الطريقة بتحديث مخزن العرض، لكنها لا ترسل المخزن إلى الشاشة نفسها. استدعِ 'update()' لعرض المخزن على الشاشة. الوسيطات: number (int): الرقم الذي سيُعرض. digit (int): الرقم الذي سيُعرض فيه. الافتراضي: 0 (الرقم الأيسر). إرجاع: النسخة (self)";
